class Solution {
public:
    int minOperations(vector<int>& nums) {
        int ans = 0;
        int top = -1;
        int n = (int)nums.size();
        for (int i = 0; i < n; i++) {
            int x = nums[i];
            while (top >= 0 && nums[top] > x) {
                top--;
            }
            if (x > 0 && (top < 0 || nums[top] != x)) {
                top++;
                nums[top] = x;
                ans++;
            }
        }
        return ans;
    }
};
